import{_ as a,o as r,c as i,a2 as s}from"./chunks/framework.D7EuCHIT.js";const f=JSON.parse('{"title":"Immersive 播放样式 (style.immersive)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/components/style-immersive.md","filePath":"reference/components/style-immersive.md","lastUpdated":1795402923000}'),t={name:"reference/components/style-immersive.md"};function l(o,e,m,c,d,n){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="immersive-播放样式-style-immersive" tabindex="-1">Immersive 播放样式 (<code>style.immersive</code>) <a class="header-anchor" href="#immersive-播放样式-style-immersive" aria-label="Permalink to &quot;Immersive 播放样式 (`style.immersive`)&quot;">​</a></h1><p>沉浸式播放页，包含自带布局、动态背景和手势切换。</p><h2 id="职责与边界" tabindex="-1">职责与边界 <a class="header-anchor" href="#职责与边界" aria-label="Permalink to &quot;职责与边界&quot;">​</a></h2><ul><li>公开能力名称 <code>style.immersive</code> 决定替换槽；插件 ID 是实现身份。</li><li>默认实现注册为同名服务；外部 <code>.so</code> 通过 <code>lyra_plugin_provide</code> 走同一替换路径。</li><li>Immersive 是集中注册的播放样式实现；自带布局与手势，参数见 immersive 配置表。</li><li>播放样式预设集中在宿主 style catalog；<code>style-picker</code> 负责列出、预览和激活，样式实现只负责自身呈现。</li></ul><h2 id="默认配置表" tabindex="-1">默认配置表 <a class="header-anchor" href="#默认配置表" aria-label="Permalink to &quot;默认配置表&quot;">​</a></h2><ul><li><code>immersive</code>：<a href="/LyraPlayer-docs-site/config/reference/ui-immersive">ui</a>（41 个键）</li></ul><h2 id="相关公开接口与文档" tabindex="-1">相关公开接口与文档 <a class="header-anchor" href="#相关公开接口与文档" aria-label="Permalink to &quot;相关公开接口与文档&quot;">​</a></h2><ul><li><a href="/LyraPlayer-docs-site/plugins/styles">Immersive 播放样式</a></li><li><a href="/LyraPlayer-docs-site/config/reference/ui-immersive">沉浸式播放页，包含自带布局、动态背景…</a></li><li><a href="/LyraPlayer-docs-site/reference/abi">公开 C SDK</a> · <a href="/LyraPlayer-docs-site/plugins/interfaces">接口指南</a> · <a href="/LyraPlayer-docs-site/plugins/service-context">服务与默认组件</a></li></ul><h2 id="平台差异" tabindex="-1">平台差异 <a class="header-anchor" href="#平台差异" aria-label="Permalink to &quot;平台差异&quot;">​</a></h2><p>Android 发布包只含 arm64-v8a，minSdk 26；平台契约为 IDL 10，VM/Activity 可为空，密度、字号、系统栏、权限和生命周期差异见 <a href="/LyraPlayer-docs-site/reference/android-platform">Android 平台契约</a>。非 Android 宿主没有可下载的 PC 宿主；arm64-v8a 插件不能作为 PC 插件加载。</p>',10)])])}const y=a(t,[["render",l]]);export{f as __pageData,y as default};
